INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (5871, 7706, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\napplication-port: ${application-dev-port:1000}\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          series: INFORMATIONAL\n          exceptions: java.net.ConnectException,org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', 'b6dee19b056d8974e5dca543d8eb3485', '2026-08-21 00:03:43', '2026-08-21 08:03:43', 'nacos', '172.18.0.1', 'U', 'dev');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 7707, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\napplication-port: ${application-dev-port:5000}\napplication-dubbo-port: ${application-dev-dubbo-port:20882}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      api-key: xxx\n      chat: \n        enabled: true\n        options: \n          model: qwen-plus\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', 'a2405930698fa0a78f269c53f89f47eb', '2026-08-21 00:04:29', '2026-08-21 08:04:30', 'nacos', '172.18.0.1', 'I', 'dev');
